import os,re,collections
root='AlgebraicJacobian'
def path(mod):
    return mod.replace('.','/')+'.lean'
imports={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            txt=open(p).read()
            imports[mod]=re.findall(r'^import\s+([A-Za-z0-9_.]+)',txt,re.M)
seeds=['AlgebraicJacobian.Picard.Pic0ChartCoveragePointwise','AlgebraicJacobian.Picard.Pic0ChartCoverageNoDrop','AlgebraicJacobian.Picard.Pic0SigmaSheaf','AlgebraicJacobian.Picard.Pic0ChartLocalSurjectivity','AlgebraicJacobian.Picard.Pic0ChartCoverageAbel','AlgebraicJacobian.Picard.Pic0ChartLocusPlusFibre','AlgebraicJacobian.Picard.Pic0ChartSplit','AlgebraicJacobian.RiemannRoch.UniformVanishing']
seen=set()
stack=list(seeds)
while stack:
    m=stack.pop()
    if m in seen or m not in imports: continue
    seen.add(m)
    stack.extend(imports[m])
print("closure size (project modules):",len(seen))
# find real sorry usage: line where sorry appears as a token not inside comment-ish line
bad=[]
for m in sorted(seen):
    p=path(m)
    for i,line in enumerate(open(p),1):
        if re.search(r'(^|[\s(\[{:=;])sorry($|[\s)\]},;])',line):
            s=line.strip()
            if s.startswith('--') or s.startswith('*') or s.startswith('/-') or '`sorry' in line:
                continue
            bad.append((p,i,s))
for b in bad: print(b)
print("real-sorry candidates:",len(bad))
EOF

